import { useState } from 'react';
import type { FormEvent } from 'react';
import {
  JxButton,
  JxCheckbox,
  JxInputField,
  JxSelect,
  JxStepper,
  JxTable,
} from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
  agreed: boolean;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
  agreed: false,
};

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);
  const [touched, setTouched] = useState(false);

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) => {
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const contactErrors = {
    name: data.name.trim() ? undefined : 'Укажите имя',
    email: /.+@.+\..+/.test(data.email) ? undefined : 'Укажите корректную почту',
  };

  const addressErrors = {
    country: data.country ? undefined : 'Выберите страну',
    city: data.city.trim() ? undefined : 'Укажите город',
    street: data.street.trim() ? undefined : 'Укажите улицу и дом',
  };

  const stepValid =
    step === 0
      ? !contactErrors.name && !contactErrors.email
      : step === 1
        ? !addressErrors.country && !addressErrors.city && !addressErrors.street
        : data.agreed;

  const goBack = () => {
    setTouched(false);
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!stepValid) {
      setTouched(true);
      return;
    }
    if (step < steps.length - 1) {
      setTouched(false);
      setStep((prev) => prev + 1);
      return;
    }
    onSubmit(data);
  };

  const countryLabel = countries.find((item) => item.value === data.country)?.label ?? '—';

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
            errorText={touched ? contactErrors.name : undefined}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={touched ? contactErrors.email : undefined}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={(event) => set('phone', event.target.value)}
            helperText="Необязательно"
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => set('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
            errorText={touched ? addressErrors.city : undefined}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={(event) => set('street', event.target.value)}
            errorText={touched ? addressErrors.street : undefined}
          />
          <JxInputField
            label="Индекс"
            value={data.zip}
            onChange={(event) => set('zip', event.target.value)}
            helperText={touched && addressErrors.country ? addressErrors.country : undefined}
          />
        </div>
      ) : null}

      {step === 2 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxTable>
            <tbody>
              <tr>
                <th scope="row">Имя</th>
                <td>{data.name}</td>
              </tr>
              <tr>
                <th scope="row">Почта</th>
                <td>{data.email}</td>
              </tr>
              <tr>
                <th scope="row">Телефон</th>
                <td>{data.phone ? `+7${data.phone}` : '—'}</td>
              </tr>
              <tr>
                <th scope="row">Страна</th>
                <td>{countryLabel}</td>
              </tr>
              <tr>
                <th scope="row">Город</th>
                <td>{data.city}</td>
              </tr>
              <tr>
                <th scope="row">Адрес</th>
                <td>{data.street}</td>
              </tr>
              <tr>
                <th scope="row">Индекс</th>
                <td>{data.zip || '—'}</td>
              </tr>
            </tbody>
          </JxTable>
          <JxCheckbox
            label="Данные верны, согласен с условиями обработки"
            checked={data.agreed}
            onChange={(event) => set('agreed', event.target.checked)}
          />
          {touched && !data.agreed ? (
            <span className="jx-input-error">Подтвердите согласие</span>
          ) : null}
        </div>
      ) : null}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {step === steps.length - 1 ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

export default RegistrationWizard;

